-- Disposable trial boundaries. Everything rolls back, including quotas.
begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
insert into auth.users(id,email,created_at,updated_at,aud,role,is_anonymous) values('97000000-0000-4000-8000-000000000001','trial-owner@example.test',now(),now(),'authenticated','authenticated',false),('97000000-0000-4000-8000-000000000002','trial-stranger@example.test',now(),now(),'authenticated','authenticated',false);
insert into auth.sessions(id,user_id,created_at,updated_at) values('97000000-0000-4000-8000-000000000011','97000000-0000-4000-8000-000000000001',now(),now()),('97000000-0000-4000-8000-000000000012','97000000-0000-4000-8000-000000000002',now(),now());
do $$ declare state jsonb; owner jsonb; stranger jsonb; manifest jsonb; bid uuid; note uuid; project uuid; price jsonb; values jsonb; draft jsonb; response jsonb; original jsonb; lease uuid:=gen_random_uuid();
begin
 owner:=public.account_browser_session('97000000-0000-4000-8000-000000000001','97000000-0000-4000-8000-000000000011',repeat('a',64),'Verified Trial Owner');
 stranger:=public.account_browser_session('97000000-0000-4000-8000-000000000002','97000000-0000-4000-8000-000000000012',repeat('b',64),'Stranger');
 state:=public.trial_start(repeat('c',64),repeat('d',64));note:=(state->>'note_id')::uuid;project:=(state->>'project_id')::uuid;
 perform pg_temp.assert_true(public.trial_read(repeat('e',64)) is null,'Guessed guest secret denied');
 perform pg_temp.assert_true(not exists(select 1 from public.projects where id=project),'No project membership before handover');
 manifest:=jsonb_build_object('captured_at',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'timezone','Africa/Lagos','assets',jsonb_build_array(jsonb_build_object('index',0,'bytes',12,'content_type','audio/ogg','sha256',repeat('f',64))));
 state:=public.trial_reserve(repeat('c',64),manifest);
 perform pg_temp.assert_true(public.trial_reserve(repeat('c',64),manifest)->>'error' is null,'Same-note reservation is retry safe');
 perform pg_temp.assert_true(public.trial_reserve(repeat('c',64),jsonb_set(manifest,'{assets,0,bytes}','13'))->>'error'='one_note','Second/replaced voice note denied');
 perform public.trial_claim_asset(repeat('c',64),0,lease);perform public.trial_finish_asset(repeat('c',64),0,lease);perform public.trial_finalize(repeat('c',64));
 perform pg_temp.assert_true(public.trial_handover(repeat('c',64),repeat('a',64))->>'error'='verify_account','Unverified browser identity cannot claim');
 update public.account_browser_identities set email_verified='trial-owner@example.test',email_verified_at=clock_timestamp() where auth_user_id='97000000-0000-4000-8000-000000000001';
 select id into bid from public.trial_prices where item_code='BLK-01';
 values:=jsonb_build_object('work_items',jsonb_build_array(jsonb_build_object('description','Guest checked blockwork','matched_boq_hint',null,'quantity',18,'unit','m2','crew',6,'confidence',1)),'materials','[]'::jsonb,'delays','[]'::jsonb,'issues','[]'::jsonb,'raw_language_notes','Original guest edit');
 draft:=jsonb_build_object('currency','NGN','source',jsonb_build_object('confirmed_at',null),'costing',jsonb_build_object('total_cost','261000','items',jsonb_build_array(jsonb_build_object('rate','14500','cost_today','261000'))));
 perform pg_temp.assert_true(public.trial_confirm(repeat('c',64),values,jsonb_build_array(bid),'[]',jsonb_set(draft,'{costing,total_cost}','"1"'))->>'error'='invalid','Invented guest money denied');
 response:=public.trial_confirm(repeat('c',64),values,jsonb_build_array(bid),'[]',draft);
 original:=(select to_jsonb(s)-'claimed_at'-'claimed_by'-'processing_owner'-'processing_until' from public.trial_sessions s where note_id=note);
 response:=public.trial_handover(repeat('c',64),repeat('a',64));
 perform pg_temp.assert_true(response->>'id'=note::text,'Active guest and verified browser proof hand over work');
 perform pg_temp.assert_true(public.trial_read(repeat('c',64)) is null,'Guest media/read capability immediately consumed');
 perform pg_temp.assert_true(public.trial_handover(repeat('c',64),repeat('a',64))->>'already_saved'='true','Lost-response retry does not create duplicates');
 update public.account_browser_identities set email_verified='trial-stranger@example.test',email_verified_at=clock_timestamp() where auth_user_id='97000000-0000-4000-8000-000000000002';
 perform pg_temp.assert_true(public.trial_handover(repeat('c',64),repeat('b',64)) is null,'Another verified account cannot reuse handover');
 perform pg_temp.assert_true((select count(*)=1 from public.projects where id=project),'One project after handover replay');
 perform pg_temp.assert_true(public.account_review(repeat('b',64),note) is null,'Stranger cannot read handed-over private work');
 perform pg_temp.assert_true(public.account_review(repeat('a',64),note)->'trial_values'=values,'Guest edits prefill verified review');
 perform pg_temp.assert_true(public.account_review(repeat('a',64),note)->>'confirmed_at' is null,'Verified confirmation remains a separate required action');
 perform pg_temp.assert_true((select to_jsonb(s)-'claimed_at'-'claimed_by'-'processing_owner'-'processing_until'=original from public.trial_sessions s where note_id=note),'Original guest evidence remains byte-equivalent');
 begin update public.trial_sessions set confirmed_values='{}' where note_id=note;raise exception 'FAIL: claimed original editable';exception when others then if sqlerrm like 'FAIL:%' then raise; end if; end;
 perform pg_temp.assert_true((select count(*)=0 from public.reports where submission_id=note),'No regular report or lock before verified confirmation');
 -- An already-expired fixture cannot be revived by knowing its hash or account ID.
 insert into public.trial_sessions(secret_hash,created_at,expires_at) values(repeat('e',64),clock_timestamp()-interval '25 hours',clock_timestamp()-interval '1 hour');
 perform pg_temp.assert_true(public.trial_read(repeat('e',64)) is null,'Expired trial read denied');
 perform pg_temp.assert_true(public.trial_handover(repeat('e',64),repeat('a',64)) is null,'Expired trial cannot be claimed');
 insert into public.trial_assets(trial_id,asset_index,path,meta) select id,0,project_id::text||'/'||note_id::text||'/0.ogg','{"index":0,"content_type":"audio/ogg","bytes":12}' from public.trial_sessions where secret_hash=repeat('e',64);
 perform pg_temp.assert_true(jsonb_array_length(public.trial_cleanup_claim())=1,'Cleanup selects only unclaimed expired media');
 perform public.trial_cleanup_finish(public.trial_cleanup_claim());
 perform pg_temp.assert_true((select cleaned_at is not null from public.trial_sessions where secret_hash=repeat('e',64)),'Expired cleanup completion is recorded');
 perform pg_temp.assert_true((select cleaned_at is null from public.trial_sessions where note_id=note),'Claimed evidence is excluded from cleanup');
 perform pg_temp.assert_true(not has_table_privilege('anon','public.trial_sessions','select'),'Anonymous direct trial table reads denied');
 perform pg_temp.assert_true(not has_function_privilege('authenticated','public.trial_handover(text,text)','execute'),'Direct authenticated RPC cannot claim another guest');
end; $$;
rollback;
